int main(void){long kb=syscall(12),ub=syscall(13); for(int i=0;i<2;i++){syscall(11,i,0);long x=syscall(SYS_fork);syscall(11,-1,0);if(x!=-1||syscall(12)!=kb||syscall(13)!=ub){syscall(SYS_print_str,"INJECT-FAIL\n");for(;;){}}} for(int i=0;i<3;i++){syscall(11,i,1);long x=syscall(SYS_fork);syscall(11,-1,1);if(x!=-1||syscall(12)!=kb||syscall(13)!=ub){syscall(SYS_print_str,"INJECT-FAIL\n");for(;;){}}} long p=syscall(SYS_fork);if(p==0){syscall(SYS_exit,9);for(;;){}}int status=-1;long got=syscall(SYS_wait,&status);if(p>0&&got==p&&status==9&&syscall(12)==kb&&syscall(13)==ub)syscall(SYS_print_str,"INJECT-PASS\n");else syscall(SYS_print_str,"INJECT-FAIL\n");for(;;){} }
